INSERT INTO "jobs"."catalogue_job_type" ("version", "key", "position", "label", "evidence", "starter_competencies") VALUES
  (1, 'software_engineering', 0, '{"en":"Software engineering"}'::jsonb, '{"en":"Repositories, shipped products, code reviews"}'::jsonb, ARRAY['System design in production', 'Code quality and testing', 'Reliability and operations', 'Delivery with a team']::text[]),
  (1, 'qa_test_automation', 1, '{"en":"QA and test automation"}'::jsonb, '{"en":"Test suites, bug reports, CI history, test plans"}'::jsonb, ARRAY['Test automation design', 'Defect finding and reporting', 'CI and release quality', 'Test strategy and risk']::text[]),
  (1, 'ai_llm_engineering', 2, '{"en":"AI and LLM engineering"}'::jsonb, '{"en":"Eval harnesses, prompt libraries, shipped assistants"}'::jsonb, ARRAY['LLM systems in production', 'Retrieval and evaluation', 'Python service engineering', 'Cost and reliability']::text[]),
  (1, 'forward_deployed_engineering', 3, '{"en":"Forward deployed engineering"}'::jsonb, '{"en":"Customer deployments, integration code, solution write-ups, customer references"}'::jsonb, ARRAY['Customer problem discovery', 'Shipping in the customer environment', 'Integration engineering', 'Working with AI systems']::text[]),
  (1, 'data_ml', 4, '{"en":"Data and machine learning"}'::jsonb, '{"en":"Notebooks, evaluation sets, model cards, results write-ups"}'::jsonb, ARRAY['Problem framing', 'Modelling and evaluation', 'Data quality and pipelines', 'Experimentation']::text[]),
  (1, 'devops_sre', 5, '{"en":"DevOps and SRE"}'::jsonb, '{"en":"Infrastructure code, incident reviews, runbooks"}'::jsonb, ARRAY['Infrastructure as code', 'Incident response', 'Observability', 'Automation and tooling']::text[]),
  (1, 'product_management', 6, '{"en":"Product management"}'::jsonb, '{"en":"Requirement documents, discovery write-ups, before-and-after metrics"}'::jsonb, ARRAY['Discovery to decision', 'Outcomes with metrics', 'Prioritisation', 'Working with engineering and design']::text[]),
  (1, 'product_design', 7, '{"en":"Product design"}'::jsonb, '{"en":"Case studies, design files, prototypes"}'::jsonb, ARRAY['Interaction design craft', 'Research to decisions', 'Design systems', 'Prototyping']::text[]),
  (1, 'sales', 8, '{"en":"Sales"}'::jsonb, '{"en":"Closed deals, client references, pipeline records, market write-ups"}'::jsonb, ARRAY['Closing sales', 'Prospecting and pipeline', 'Client relationships', 'Negotiation']::text[]),
  (1, 'technical_writing_support', 9, '{"en":"Technical writing and support"}'::jsonb, '{"en":"Published documentation, resolved tickets, help articles"}'::jsonb, ARRAY['Clear task documentation', 'Understanding the product', 'Information structure', 'Working from tickets and feedback']::text[])
