  (1, 'payments_fintech', 0, '{"en":"Payments and fintech"}'::jsonb),
  (1, 'banking_islamic_finance', 1, '{"en":"Banking and Islamic finance"}'::jsonb),
  (1, 'healthcare', 2, '{"en":"Healthcare"}'::jsonb),
  (1, 'ecommerce_marketplaces', 3, '{"en":"E-commerce and marketplaces"}'::jsonb),
  (1, 'logistics_mobility', 4, '{"en":"Logistics and mobility"}'::jsonb),
