INSERT INTO "jobs"."catalogue_pack_competency" ("version", "pack_key", "position", "name", "meaning", "evidence", "level_1", "level_3", "level_5", "applies_to", "level_needed", "type", "core") VALUES
  (1, 'payments_fintech', 0, 'Idempotent payment APIs and retries', 'Makes sure a payment request that is retried, times out or arrives twice moves money exactly once.', 'Code with idempotency keys and retry tests; incident reviews of duplicate charges; design documents', 'Has called a payment API and handled declines', 'Built an endpoint where a retried charge is applied once, with tests that prove it', 'Designed retry, timeout and idempotency rules across services, with evidence a duplicate charge cannot happen under failure', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'devops_sre']::text[], 3, 'desirable', ARRAY['software_engineering']::text[]),
  (1, 'payments_fintech', 1, 'Ledger and double-entry accounting', 'Records every money movement as balanced debit and credit entries in an append-only ledger, so any balance can be rebuilt and explained.', 'Ledger schemas and posting code with balance invariants; posting and reversal tests; write-ups of balance discrepancies found and fixed', 'Has queried a ledger and can explain how one payment becomes a debit and a credit', 'Built postings, reversals and fees that always balance, with tests that check the invariant', 'Designed a multi-currency ledger with immutable entries and balances rebuilt from entries, running in production', ARRAY['software_engineering', 'qa_test_automation', 'data_ml']::text[], 3, 'desirable', ARRAY['software_engineering']::text[]),
  (1, 'payments_fintech', 2, 'Reconciliation and settlement', 'Matches internal records against acquirer, scheme and bank settlement files, and clears breaks before money is lost or misreported.', 'Reconciliation jobs and their matching rules; break reports and how they were cleared; settlement file parsers with tests', 'Has traced a mismatch between an internal record and a settlement report', 'Built an automated reconciliation that matches settlement files to transactions and reports breaks, with tests for partial and late settlement', 'Designed reconciliation across several acquirers, currencies and settlement cycles, with measured break rates and a process for clearing them', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'devops_sre']::text[], 3, 'desirable', ARRAY['software_engineering']::text[]),
  (1, 'payments_fintech', 3, 'PCI DSS scope reduction and tokenisation', 'Keeps card data out of as many systems as possible with tokens, hosted fields or a vault, and knows what the remaining scope demands.', 'Architecture diagrams that mark the cardholder data environment; tokenisation or vault integration code; assessment or self-assessment work', 'Can explain which card data is in scope, why card numbers must never be logged, and why security codes must never be stored after authorisation', 'Built a flow where raw card numbers never reach the team’s own servers, using tokens or hosted fields', 'Led a scope reduction that took systems out of the cardholder data environment, with the assessment evidence to show it', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'devops_sre']::text[], 3, 'desirable', ARRAY['software_engineering']::text[]),
  (1, 'payments_fintech', 4, '3-D Secure and SCA flows', 'Integrates cardholder authentication so challenges, frictionless approvals, exemptions and failures are handled without losing good payments.', 'Checkout code that handles each authentication result; test runs of challenge and frictionless cases; exemption or approval-rate analyses', 'Has integrated a checkout that triggers a 3-D Secure challenge', 'Handled challenge, frictionless, failed and abandoned authentication, with the liability shift recorded per payment', 'Designed an exemption and retry strategy across markets that raised approval rates within each market’s authentication rules, with before-and-after data', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'product_design']::text[], 2, 'desirable', ARRAY[]::text[]),
  (1, 'payments_fintech', 5, 'Fraud and risk signals', 'Scores payment risk from device, behaviour, velocity and transaction signals, and weighs fraud losses against good customers declined.', 'Feature pipelines and rules; model evaluations with catch rate and false-decline rate; fraud incident analyses', 'Has written or tuned a velocity or blocklist rule', 'Built a risk score or rule set and measured its catch rate against false declines on labelled data', 'Owned rules, models and manual review in production, with chargeback and false-decline trends to show for it', ARRAY['software_engineering', 'data_ml', 'ai_llm_engineering', 'product_management']::text[], 3, 'desirable', ARRAY['data_ml']::text[]),
  (1, 'payments_fintech', 6, 'Payment gateway and acquirer integration with webhooks', 'Integrates gateways and acquirers so authorisations, captures, refunds and asynchronous webhook events stay consistent with the merchant’s records.', 'Integration code for authorise, capture, refund and void; webhook handlers with signature checks and replay handling; certification records', 'Has integrated a gateway’s hosted checkout or client library', 'Built a server-side integration whose webhook handling is signed, idempotent and tested for out-of-order events', 'Designed routing across several acquirers with failover, keeping state consistent when webhooks arrive late, twice or never', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'devops_sre']::text[], 3, 'desirable', ARRAY[]::text[]),
  (1, 'payments_fintech', 7, 'ISO 8583 and ISO 20022 messaging', 'Reads, builds and maps card authorisation messages and account-to-account payment messages, including field rules, response codes and reversals.', 'Message parsers or mappers with tests; switch or host integration code; mapping specifications between formats', 'Can read an ISO 8583 or ISO 20022 message and explain its key fields', 'Built a parser or mapper for one of the formats, with tests for bitmaps, field formats or schema validation', 'Designed a translation layer between card or bank networks and internal services, with response codes and reversals handled in production', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering']::text[], 2, 'desirable', ARRAY[]::text[]),
  (1, 'payments_fintech', 8, 'Authorisation and conversion rates', 'Reads the payment funnel from checkout to authorisation and settlement, finds where good payments fail, and moves the rate.', 'Before-and-after approval or conversion metrics; decline-code analyses; experiment write-ups', 'Can tell a decline from an authentication failure and an abandoned checkout', 'Shipped a change, such as retry rules, routing or a checkout step, that raised the approval rate, with the data to show it', 'Owned approval and conversion targets across markets and methods, with a record of decisions and their measured effect', ARRAY['product_management', 'data_ml']::text[], 3, 'desirable', ARRAY['product_management']::text[]),
  (1, 'payments_fintech', 9, 'Scheme and regulatory rules', 'Turns card scheme rules and payment regulation into product requirements before launch, not after an audit.', 'Requirement documents that cite the rule they meet; compliance reviews; launch checklists for a new market or method', 'Knows which scheme and regulatory rules apply to the product and where to read them', 'Wrote requirements for a feature from a scheme or regulatory rule and saw it through review', 'Led a product through a licence, scheme or regulatory change, with the requirement trail and the outcome documented', ARRAY['product_management']::text[], 2, 'desirable', ARRAY['product_management']::text[]),
  (1, 'payments_fintech', 10, 'Payment methods by market', 'Chooses and sequences cards, wallets, bank transfers, instant payments and cash-based methods for each market from usage and cost data.', 'Market analyses with method mix and cost; launch plans; adoption metrics after launch', 'Can describe the payment methods customers use in one market and what each costs to accept', 'Launched a payment method in a market and measured its adoption and cost', 'Set the payment method strategy across several markets, with adoption, cost and approval data behind each choice', ARRAY['product_management', 'sales']::text[], 2, 'desirable', ARRAY['product_management']::text[]),
  (1, 'payments_fintech', 11, 'Disputes and chargebacks', 'Designs how disputes are received, evidenced and answered within scheme deadlines, and removes the causes that create them.', 'Dispute flow designs; win-rate and chargeback-ratio metrics; root-cause analyses', 'Can explain the chargeback lifecycle from first notice to arbitration', 'Improved a dispute process, such as evidence packs or deadline tracking, with a measured change in win rate or ratio', 'Kept chargeback ratios inside scheme thresholds across markets, with the programme and the data to show it', ARRAY['product_management', 'data_ml', 'technical_writing_support']::text[], 2, 'desirable', ARRAY['product_management']::text[]),
  (1, 'payments_fintech', 12, 'Payment certification and test cards', 'Plans and runs the cases a gateway, acquirer or scheme requires before go-live, with test cards, simulators and response codes.', 'Certification test plans and results; automated suites using scheme test cards and simulators; defect reports from certification runs', 'Has run payments through a sandbox with test cards and checked each result', 'Automated the certification cases for an integration, including declines, reversals and timeouts', 'Led certification for several acquirers or a new scheme, with test evidence accepted on first submission', ARRAY['qa_test_automation', 'forward_deployed_engineering']::text[], 3, 'desirable', ARRAY['qa_test_automation']::text[]),
  (1, 'banking_islamic_finance', 0, 'Core banking integration', 'Connects channels and services to the core banking system for accounts, postings, holds and end-of-day processing, without breaking the books of record.', 'Integration code against core banking interfaces with tests; designs for postings, holds and end-of-day cut-off; incident reviews of failed or duplicate postings', 'Has read account or transaction data through a core banking interface', 'Built a service that posts to a core banking system with idempotent retries and end-of-day cut-off handled, with tests', 'Designed the integration layer between digital channels and a core banking system, including an upgrade or migration with balances reconciled', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'devops_sre']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering']::text[]),
  (1, 'banking_islamic_finance', 1, 'AML/CFT transaction monitoring', 'Builds the scenarios, rules and alert workflows that flag suspicious transactions for investigators, and tunes them so alerts carry real risk rather than noise.', 'Monitoring rules or models with test data; alert volume and true-positive analyses; case management workflow designs', 'Can explain typologies such as structuring and rapid movement of funds that a monitoring rule looks for', 'Built or tuned monitoring scenarios and measured alert volume and true-positive rate before and after', 'Owned transaction monitoring from typologies to alerts, cases and suspicious transaction reports, with model validation evidence', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'ai_llm_engineering', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'data_ml', 'product_management']::text[]),
  (1, 'banking_islamic_finance', 2, 'KYC, eKYC and sanctions screening', 'Builds onboarding that verifies identity documents and liveness, screens names against sanctions and watch lists, and routes possible matches to review with each decision recorded.', 'Onboarding flow code and tests; name-matching logic with test cases for spelling variants and transliterated Arabic names; review queue designs and audit records', 'Can explain customer due diligence, enhanced due diligence and why screening must handle name variants', 'Built an onboarding or screening flow with document checks, fuzzy name matching and a review queue, with tests for transliterated names', 'Designed onboarding and screening across products, with false-match rates measured and a decision trail that passed audit', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'data_ml', 'product_management', 'product_design']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'product_management']::text[]),
  (1, 'banking_islamic_finance', 3, 'Islamic finance products (murabaha, ijara) in systems', 'Models Islamic finance contracts such as murabaha, ijara, musharaka and sukuk in systems, so profit, asset ownership, early settlement and late-payment charity follow the structure the Sharia board approved.', 'Product and system designs that follow AAOIFI standards; profit schedule and early settlement code with tests; product reviews signed off by the Sharia board', 'Can explain how a murabaha sale differs from an interest-bearing loan, and what ijara means for who owns the asset', 'Built profit schedules, early settlement or ijara rentals for an Islamic finance product, with tests checked against the approved structure', 'Designed an Islamic finance product line in systems, such as sukuk or diminishing musharaka, with Sharia board and audit sign-off recorded', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'product_management']::text[], 2, 'desirable', ARRAY['software_engineering', 'product_management']::text[]),
  (1, 'banking_islamic_finance', 4, 'Open banking APIs', 'Publishes or consumes account information and payment initiation APIs with customer consent, strong authentication and the security profile the framework requires.', 'API specifications and consent flow code; conformance or certification test results; security profile configuration such as mutual TLS and signed requests', 'Can explain account information, payment initiation and the consent a customer gives for each', 'Built an open banking API or client with consent, token handling and conformance tests passing', 'Led a bank’s open banking platform through certification, with consent management, monitoring and third-party onboarding', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'devops_sre', 'product_management']::text[], 2, 'desirable', ARRAY['forward_deployed_engineering', 'product_management']::text[]),
  (1, 'banking_islamic_finance', 5, 'Basel and IFRS 9 risk reporting', 'Builds the data and models behind expected credit loss, capital and liquidity reports, with lineage a regulator or auditor can follow back to the ledger.', 'Expected credit loss, capital or liquidity calculation code; data lineage and reconciliation to the general ledger; model validation or audit findings closed', 'Can explain the three IFRS 9 stages and what probability of default, loss given default and exposure at default mean', 'Built an expected credit loss, capital or liquidity calculation that reconciles to the ledger, with tests', 'Owned a regulatory risk reporting pipeline through audit, with lineage, controls and model validation evidence', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'ai_llm_engineering']::text[], 3, 'desirable', ARRAY['data_ml']::text[]),
  (1, 'banking_islamic_finance', 6, 'Interest, profit and fee calculation testing', 'Proves that interest, profit, fees and rounding are right across day counts, holidays, month ends and rate changes, before a customer or an auditor finds the error.', 'Automated suites with boundary dates and rate changes; calculation defects found and their root causes; comparisons against an independent calculation', 'Can explain day-count conventions and why a month end or a holiday changes a calculation', 'Automated calculation tests over day counts, holidays and rate changes, and found a defect with them', 'Built the calculation test strategy for several products, with an independent model the bank uses as its check', ARRAY['qa_test_automation', 'software_engineering']::text[], 3, 'desirable', ARRAY['qa_test_automation']::text[]),
  (1, 'banking_islamic_finance', 7, 'Operational resilience and change control', 'Runs critical banking services with tested disaster recovery, controlled changes and segregation of duties, and keeps the evidence regulators and auditors accept.', 'Disaster recovery test reports; change records with approvals and segregation of duties; outage reviews', 'Can explain why a production change at a bank needs approval, a rollback plan and segregation of duties', 'Ran a disaster recovery test or a controlled release with the evidence pack an auditor accepted', 'Designed resilience and change control for critical banking services, with recovery time targets met in tests', ARRAY['devops_sre', 'software_engineering']::text[], 3, 'desirable', ARRAY['devops_sre']::text[]),
  (1, 'healthcare', 0, 'HL7 v2 messaging and FHIR R4 APIs', 'Builds and maps clinical messages and resources, from HL7 v2 ADT and ORU feeds to FHIR R4 REST APIs and profiles.', 'Interface code or mappings with tests; FHIR profiles or implementation guides used; validator results', 'Can read an HL7 v2 message and a FHIR resource and explain their main segments or elements', 'Built an interface that maps HL7 v2 messages to FHIR resources, or a FHIR API that passes a validator, with tests', 'Designed an integration layer for several message types, versions and profiles, with error queues and reprocessing in production', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'data_ml', 'ai_llm_engineering']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering']::text[]),
  (1, 'healthcare', 1, 'Clinical data privacy and consent', 'Protects health information with role-based access, consent records, minimum necessary access and audit, as health data law requires.', 'Access control and consent designs; audit log implementations; privacy impact assessments', 'Knows what counts as protected health information and why it must never reach logs or test data', 'Built consent capture and access checks so a record is shown only to those allowed to see it, with audit entries', 'Designed privacy controls across a health platform, including emergency access, consent withdrawal and audit review, with assessment evidence', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'data_ml', 'ai_llm_engineering', 'devops_sre', 'product_management', 'product_design']::text[], 3, 'desirable', ARRAY['software_engineering', 'data_ml', 'ai_llm_engineering', 'devops_sre', 'product_management']::text[]),
  (1, 'healthcare', 2, 'Clinical coding (ICD-10, CPT) and claims', 'Works with diagnosis and procedure codes, or the market’s own code sets, and the claim lifecycle, from eligibility and coding to submission, rejection and resubmission.', 'Claims or coding logic with tests; rejection analyses; data models for code sets and their versions', 'Can explain how a diagnosis code and a procedure code support a claim', 'Built claim validation or submission that reduced rejections, with the rejection data to show it', 'Designed a claims platform for several payers’ rules and code set updates, with measured rejection and turnaround rates', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'data_ml', 'ai_llm_engineering', 'product_management']::text[], 2, 'desirable', ARRAY['data_ml', 'product_management']::text[]),
  (1, 'healthcare', 3, 'Interoperability with EMR systems', 'Connects products to electronic medical record systems through their interfaces, integration engines and launch frameworks such as SMART on FHIR.', 'Integration code and interface specifications; go-live records from hospital deployments; integration engine configurations', 'Has worked with data sent to or exported from an EMR', 'Built and took live an integration with an EMR, handling patient matching and failed messages', 'Led integrations with several EMRs across hospitals, with a repeatable approach and support records', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'forward_deployed_engineering']::text[]),
  (1, 'healthcare', 4, 'Clinical safety and audit trails', 'Identifies how software could harm a patient, records the hazards and their controls, and keeps a tamper-evident trail of clinical actions.', 'Hazard logs and safety cases; audit trail designs and tests; clinical incident reviews', 'Can explain why a change to a clinical record needs who, when and why', 'Built an audit trail for clinical actions and added hazards and controls to a safety case', 'Led clinical risk management for a product, with a hazard log, safety case and incident learning in use', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'data_ml', 'ai_llm_engineering', 'product_management', 'product_design']::text[], 2, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'ai_llm_engineering', 'product_management']::text[]),
  (1, 'ecommerce_marketplaces', 0, 'Catalogue and search relevance', 'Structures product data and tunes search so shoppers find the right item, including synonyms, typos, attributes and mixed-language queries.', 'Search ranking code or configuration; offline relevance metrics and online experiment results; catalogue data quality work', 'Can explain how a product index, filters and ranking fit together', 'Improved search relevance with a measured change in click-through, zero-result rate or conversion', 'Owned search and catalogue quality across categories and languages, including Arabic and transliterated queries, with a relevance evaluation the team trusts', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'ai_llm_engineering', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'data_ml', 'ai_llm_engineering']::text[]),
  (1, 'ecommerce_marketplaces', 1, 'Checkout and cart at peak load', 'Keeps cart, pricing, stock reservation and checkout correct and fast during sale events, when traffic is many times normal.', 'Load test plans and results; capacity and incident reviews from sale events; code for stock reservation and price consistency', 'Can explain why stock and price must be checked again at checkout', 'Load-tested a checkout to a sale-day target and fixed the bottleneck it found', 'Ran checkout through several peak sale events with error and latency targets met, and the capacity plan behind it', ARRAY['software_engineering', 'qa_test_automation', 'devops_sre', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'devops_sre']::text[]),
  (1, 'ecommerce_marketplaces', 2, 'Marketplace seller payouts', 'Onboards and verifies sellers, then calculates commissions, fees, refunds and holds so each seller is paid the right amount on time.', 'Payout and commission calculation code with tests; seller ledger designs; payout reconciliation reports', 'Can explain how a seller payout is built from orders, commission, refunds and fees', 'Built seller payout calculation with commission rules, refunds and holds, reconciled against payments', 'Designed seller onboarding and payouts at scale across currencies, with reconciliation and dispute data owned', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'data_ml', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'product_management']::text[]),
  (1, 'ecommerce_marketplaces', 3, 'Cash on delivery reconciliation', 'Reconciles cash collected by couriers against orders and remittances, and handles refused deliveries, partial payments and late remittance.', 'Reconciliation jobs and matching rules; remittance and break reports; refused-delivery analyses', 'Can explain the cash-on-delivery lifecycle from order to courier remittance', 'Built cash-on-delivery reconciliation that matched remittances to orders and reported breaks', 'Owned cash on delivery across couriers and markets, with refusal, remittance delay and loss data and the actions taken to reduce them', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'data_ml']::text[]),
  (1, 'ecommerce_marketplaces', 4, 'Order management and returns', 'Models the order lifecycle across split shipments, cancellations, returns and refunds, so stock, money and customer messages stay in step.', 'Order state machine code and tests; return and refund flow designs; return rate analyses', 'Can explain the states an order passes through from payment to delivery or return', 'Built order or return flows with split shipments and partial refunds, with tests for each transition', 'Designed order management across warehouses, sellers and carriers, with return rates and refund times measured and improved', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'technical_writing_support']::text[], 3, 'desirable', ARRAY['qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[]),
  (1, 'ecommerce_marketplaces', 5, 'Checkout conversion and experimentation', 'Finds where shoppers drop out of the funnel and runs controlled experiments that move conversion without hurting margin.', 'Experiment designs and results with sample sizes; funnel analyses; before-and-after conversion data', 'Can read a funnel and name the step where shoppers drop out', 'Ran a controlled experiment on a checkout or product page and shipped the winner, with the analysis to show it', 'Owned conversion targets across web and app, with an experimentation programme and documented results', ARRAY['product_management', 'product_design', 'data_ml']::text[], 2, 'desirable', ARRAY['product_management', 'product_design', 'data_ml']::text[]),
  (1, 'ecommerce_marketplaces', 6, 'Recommendations and personalisation', 'Recommends products from browsing and purchase signals, and measures the lift against a fair baseline rather than clicks alone.', 'Recommender code or models; offline evaluations and online experiment results; cold-start handling', 'Can explain collaborative filtering and the cold-start problem', 'Built a recommender and measured its lift in an online experiment', 'Owned recommendations across surfaces, with evaluation, guardrails and measured revenue effect', ARRAY['data_ml', 'ai_llm_engineering', 'software_engineering']::text[], 2, 'desirable', ARRAY['data_ml']::text[]),
  (1, 'logistics_mobility', 0, 'Route and dispatch optimisation', 'Plans routes and assigns jobs to drivers or vehicles under time windows, capacity and traffic, and re-plans when the day changes.', 'Routing or assignment code with benchmarks; before-and-after distance, cost or on-time data; solver configurations', 'Can explain the vehicle routing problem and why time windows make it harder', 'Built or tuned a routing or dispatch solver and measured its effect on distance, cost or on-time rate', 'Owned routing and dispatch in production at scale, including real-time re-planning, with measured savings', ARRAY['software_engineering', 'data_ml', 'ai_llm_engineering', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'data_ml']::text[]),
  (1, 'logistics_mobility', 1, 'Warehouse management systems', 'Builds or integrates warehouse systems for receiving, putaway, picking, packing and cycle counts, so stock records match the shelves.', 'Warehouse system module or integration code; pick-path or slotting analyses; stock accuracy reports', 'Can explain the flow from receiving to dispatch in a warehouse', 'Built or integrated a warehouse flow such as picking or cycle counts, with tests and stock accuracy measured', 'Designed warehouse systems across sites, with throughput and stock accuracy targets met', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'data_ml', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering']::text[]),
  (1, 'logistics_mobility', 2, 'Real-time tracking and ETAs', 'Ingests location events from vehicles and couriers, and predicts arrival times that customers and operations can trust.', 'Event ingestion code; arrival-time model evaluations with error measures; incident reviews of tracking gaps', 'Can explain how location events become a shipment status and an estimated arrival time', 'Built tracking ingestion or an arrival-time model, with its error measured against actual arrivals', 'Owned real-time tracking at scale, with latency, gap and arrival-time error targets met', ARRAY['software_engineering', 'data_ml', 'ai_llm_engineering', 'devops_sre', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'data_ml', 'devops_sre']::text[]),
  (1, 'logistics_mobility', 3, 'Carrier and customs integration', 'Connects carriers and customs systems for bookings, labels, tracking events and customs declarations with harmonised system codes.', 'Carrier and customs integration code with tests; declaration mappings; rejection or hold analyses', 'Can explain what a customs declaration contains and why a harmonised system code matters', 'Built a carrier or customs integration with tests for rejections and holds', 'Designed integrations with many carriers and customs systems, with rejection and clearance times measured', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[]),
  (1, 'logistics_mobility', 4, 'Last-mile delivery and proof of delivery', 'Designs the last-mile flow from dispatch to proof of delivery, failed attempts and returns, and measures first-attempt success.', 'Driver and customer flow designs; first-attempt and failed-delivery analyses; proof-of-delivery data', 'Can explain why deliveries fail on the first attempt and what proof of delivery records', 'Shipped a change to the delivery flow that raised first-attempt success, with the data to show it', 'Owned last-mile delivery outcomes across cities, with a record of decisions and their measured effect', ARRAY['product_management', 'product_design', 'software_engineering', 'data_ml']::text[], 2, 'desirable', ARRAY['product_management', 'product_design']::text[]),
  (1, 'logistics_mobility', 5, 'Volume forecasting and capacity planning', 'Forecasts shipment volume and plans fleet, drivers and warehouse shifts, so service levels hold at peak without idle capacity off-peak.', 'Forecast models with error measures; capacity plans; service-level and cost data after peaks', 'Can explain how a volume forecast turns into a fleet or shift plan', 'Built a volume forecast used for capacity planning, with its error measured', 'Owned forecasting and capacity planning across peaks, with service-level and cost results', ARRAY['product_management', 'data_ml']::text[], 2, 'desirable', ARRAY['product_management', 'data_ml']::text[]),
  (1, 'government_public_sector', 0, 'National digital identity sign-in', 'Integrates sign-in and identity assurance from a government identity provider over OIDC or SAML, with assurance levels, consent and fallback handled.', 'Identity integration code with tests for each assurance level; sign-in failure and fallback designs; security review records', 'Can explain how an OIDC or SAML sign-in works and what an assurance level means', 'Built sign-in with a government identity provider in a staging environment, with assurance, failure and fallback cases tested', 'Owned identity sign-in for several services in production, with completion rates, incidents and security reviews owned', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'devops_sre']::text[], 3, 'desirable', ARRAY['software_engineering', 'forward_deployed_engineering']::text[]),
  (1, 'government_public_sector', 1, 'Arabic-first and accessible services', 'Builds bilingual services that work right to left with Arabic as the first language, and that meet accessibility standards for screen readers, zoom and keyboard.', 'Right-to-left layouts and bilingual content handling; WCAG 2.2 AA audits and fixes; test sessions with screen readers', 'Can explain what changes when a page switches to right to left, and how a WCAG success criterion is tested', 'Shipped a bilingual service with a right-to-left layout that passed a WCAG 2.2 AA audit', 'Set the bilingual and accessibility standard for several services, with audits, user testing and fixes tracked', ARRAY['software_engineering', 'qa_test_automation', 'product_management', 'product_design', 'technical_writing_support']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'product_management', 'product_design', 'technical_writing_support']::text[]),
  (1, 'government_public_sector', 2, 'Data classification and security frameworks', 'Classifies government data, applies the controls each class requires, and keeps the evidence an assessor checks against the applicable security framework.', 'Classification schemes and control mappings; security assessment or audit evidence; remediation records', 'Can explain how data classes differ and which controls each class needs', 'Mapped a service’s controls to a security framework and closed the findings of its assessment', 'Led a platform through a security framework assessment, with control evidence kept current', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'devops_sre', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'data_ml', 'devops_sre']::text[]),
  (1, 'government_public_sector', 3, 'Service integration across agencies', 'Connects services across agencies through a government service bus or API gateway, with data sharing agreements, consent and audit.', 'Integration code and API specifications; data sharing designs; monitoring and audit records', 'Can explain why a service should fetch a record from another agency instead of asking for it again', 'Built an integration between agencies with consent and audit, with tests for failures and timeouts', 'Designed integration across several agencies, with data sharing agreements, monitoring and audit in production', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'devops_sre', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'forward_deployed_engineering']::text[]),
  (1, 'government_public_sector', 4, 'Public tender and service-level delivery', 'Turns tender requirements, service-level agreements and government service standards into a delivery plan with acceptance evidence for each requirement.', 'Requirement traceability matrices; acceptance test records; service-level reports', 'Can read a tender’s requirements and say how each would be accepted', 'Delivered a public sector project against its requirements, with traceability and acceptance records', 'Led several public sector programmes from tender to acceptance, with service levels met and documented', ARRAY['product_management', 'forward_deployed_engineering', 'technical_writing_support', 'sales']::text[], 2, 'desirable', ARRAY['product_management', 'sales']::text[]),
  (1, 'government_public_sector', 5, 'Life-event service design', 'Designs public services around life events, measures completion and satisfaction, and removes steps and documents people should not have to provide twice.', 'Service blueprints and journey maps; completion and satisfaction data before and after; research findings', 'Can explain how a life event spans several services and agencies', 'Redesigned a public service journey and measured the change in completion or time taken', 'Led the design of a life-event journey across agencies, with measured results', ARRAY['product_design', 'product_management', 'data_ml']::text[], 2, 'desirable', ARRAY['product_design', 'product_management']::text[]),
  (1, 'telecom', 0, 'OSS/BSS systems', 'Builds or integrates operations and business support systems for catalogue, order management, inventory, charging and assurance, so a sold service becomes a working one.', 'OSS or BSS integration code; order-to-activation flow designs; order fallout analyses', 'Can explain what OSS and BSS each cover and how an order moves between them', 'Built an order-to-activation flow across OSS and BSS, with fallout cases tested', 'Designed OSS and BSS integration for several products, with order fallout and activation times measured', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'devops_sre', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[]),
  (1, 'telecom', 1, 'TM Forum Open APIs', 'Exposes and consumes the standard TM Forum Open APIs for product catalogue, ordering, inventory and trouble tickets, so systems can be replaced without rewrites.', 'API implementations and conformance results; mappings between internal models and the standard data model; integration tests', 'Can explain which TM Forum Open APIs cover catalogue, ordering and inventory', 'Built an implementation or client of one of the APIs that passed conformance tests', 'Designed an API layer on the standard APIs across several systems, with conformance and change records', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering']::text[], 2, 'desirable', ARRAY['software_engineering', 'forward_deployed_engineering']::text[]),
  (1, 'telecom', 2, '5G core and network functions', 'Builds, deploys or tests cloud-native network functions of a 5G core, such as AMF, SMF and UPF, and their service-based interfaces.', 'Network function code, deployment charts or test results; interface traces; performance and failover test reports', 'Can explain the main 5G core network functions and what each does in a session', 'Built, deployed or tested a network function with traces and failover tests', 'Owned a 5G core deployment or product, with performance, failover and upgrade results', ARRAY['software_engineering', 'qa_test_automation', 'devops_sre']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation', 'devops_sre']::text[]),
  (1, 'telecom', 3, 'Number portability and provisioning', 'Handles number porting between operators, SIM and eSIM provisioning and service activation, within the deadlines the regulator sets.', 'Porting and provisioning code with tests for rejections and rollbacks; activation time metrics; incident reviews', 'Can explain the steps of a port request and why it can be rejected', 'Built porting or eSIM provisioning with rejection and rollback cases tested', 'Owned porting and provisioning in production within regulatory deadlines, with activation data', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'qa_test_automation']::text[]),
  (1, 'telecom', 4, 'Billing mediation and charging', 'Collects usage records from the network, mediates and rates them, and turns them into correct charges, including roaming and interconnect.', 'Mediation or rating code with tests; usage record reconciliation; revenue assurance findings', 'Can explain how a usage record becomes a charge on a bill', 'Built mediation or rating rules with tests, and reconciled usage records against charges', 'Owned mediation and charging for several products, with revenue assurance findings closed', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'product_management']::text[], 3, 'desirable', ARRAY['data_ml', 'product_management']::text[]),
  (1, 'telecom', 5, 'Network automation', 'Automates network configuration, provisioning and closed-loop fixes with NETCONF and YANG models, telemetry and orchestration instead of manual changes.', 'Automation code and YANG models or templates; change failure rates before and after; orchestration runbooks', 'Can explain how a YANG model and NETCONF change a device’s configuration', 'Automated a network change or closed-loop fix and measured the change failure rate', 'Led network automation across domains, with manual changes and failures measured down', ARRAY['software_engineering', 'devops_sre', 'data_ml', 'ai_llm_engineering']::text[], 3, 'desirable', ARRAY['devops_sre']::text[]),
  (1, 'telecom', 6, 'Network quality and churn analytics', 'Turns network counters, usage and customer data into churn, quality and capacity insights that operations and marketing act on.', 'Models or dashboards with evaluation; churn or quality analyses; decisions taken from them', 'Can explain the main network quality counters and how they relate to churn', 'Built a churn or quality model and measured its accuracy and the action it drove', 'Owned network and churn analytics, with models in production and measured results', ARRAY['data_ml', 'ai_llm_engineering', 'product_management']::text[], 2, 'desirable', ARRAY['data_ml', 'product_management']::text[]),
  (1, 'energy_utilities', 0, 'OT and SCADA security (IEC 62443)', 'Secures industrial control systems with zones and conduits, controlled remote access and monitoring that follow IEC 62443, without stopping the process.', 'Zone and conduit designs; OT security assessments and remediation records; incident response playbooks for control systems', 'Can explain how OT security differs from IT security, and why availability and safety come first', 'Designed or implemented zones, conduits or remote access for a control system, with an assessment to show it', 'Led an OT security programme across sites, with assessments, monitoring and incident drills recorded', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'devops_sre']::text[], 3, 'desirable', ARRAY['software_engineering', 'forward_deployed_engineering', 'devops_sre']::text[]),
  (1, 'energy_utilities', 1, 'Asset integrity and maintenance data', 'Builds data and software for inspection, maintenance and asset health, so failures are predicted and integrity can be proven to auditors.', 'Maintenance and inspection data models; reliability or predictive maintenance analyses; integrations with work management systems', 'Can explain the difference between planned, condition-based and predictive maintenance', 'Built a maintenance or inspection data flow, or a failure prediction measured against actual failures', 'Owned asset integrity data across a fleet of assets, with reliability gains and audit results', ARRAY['software_engineering', 'forward_deployed_engineering', 'data_ml', 'ai_llm_engineering', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'data_ml']::text[]),
  (1, 'energy_utilities', 2, 'Smart metering and grid data', 'Ingests and validates interval meter readings and grid telemetry at scale, from head-end systems to billing, outage and load analytics.', 'Meter data pipelines with validation, estimation and editing (VEE) rules; time-series storage designs; data quality reports', 'Can explain how an interval reading travels from a meter to a bill', 'Built a meter data pipeline with VEE rules and data quality measured', 'Owned meter and grid data at the scale of millions of meters, with completeness and latency targets met', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'devops_sre', 'product_management']::text[], 3, 'desirable', ARRAY['software_engineering', 'data_ml', 'devops_sre']::text[]),
  (1, 'energy_utilities', 3, 'HSE incident reporting systems', 'Builds systems for reporting incidents, near misses and permits to work, so investigations, actions and safety metrics are complete and on time.', 'Incident and permit-to-work system designs; workflow and notification tests; safety metric reports built from the data', 'Can explain the incident lifecycle from report to investigation and closed action', 'Built incident or permit-to-work flows with notifications and tests, used on site', 'Owned an HSE reporting platform across sites, with reporting rates and action closure measured', ARRAY['software_engineering', 'qa_test_automation', 'data_ml', 'product_management', 'product_design']::text[], 2, 'desirable', ARRAY['software_engineering', 'product_management', 'product_design']::text[]),
  (1, 'energy_utilities', 4, 'Industrial protocols and historians', 'Reads and writes field data over Modbus, DNP3, IEC 61850 or OPC UA, and stores it in process historians with timestamps and quality flags intact.', 'Protocol integration code with tests or simulators; historian configurations; data quality analyses', 'Can explain what a tag, a quality flag and a polling cycle are', 'Built an integration over one of the protocols into a historian, tested against a simulator', 'Designed field data acquisition across sites and protocols, with data quality and latency measured', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'data_ml', 'devops_sre']::text[], 2, 'desirable', ARRAY['qa_test_automation', 'forward_deployed_engineering']::text[]),
  (1, 'energy_utilities', 5, 'Load and renewable generation forecasting', 'Forecasts demand and solar or wind output from weather and history, and states the error so grid and trading decisions can rely on it.', 'Forecast models with error measures by horizon; backtests; decisions taken from the forecasts', 'Can explain why forecast error matters more at some horizons than others', 'Built a load or generation forecast and measured its error against actuals', 'Owned forecasting used in grid or trading operations, with error targets met', ARRAY['data_ml', 'ai_llm_engineering', 'product_management']::text[], 2, 'desirable', ARRAY['data_ml', 'product_management']::text[])
INSERT INTO "jobs"."catalogue_regional_hint" ("version", "pack_key", "region", "position", "name", "meaning", "evidence", "level_1", "level_3", "level_5", "applies_to", "level_needed", "type") VALUES
  (1, 'payments_fintech', 'uae', 0, 'CBUAE payment and stored-value rules', 'Knows the CBUAE rules for retail payment services and stored-value facilities, and how they shape limits, safeguarding and onboarding.', 'Requirement documents or compliance write-ups that apply the rules; integration code for features built to meet them', 'Can name the licence categories and what each allows', 'Built or specified a feature to meet a stored-value or payment-service rule, with the review trail', 'Led a product’s compliance with these rules through licensing or inspection, with the evidence pack', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 2, 'desirable'),
  (1, 'payments_fintech', 'uae', 1, 'Aani instant payments', 'Integrates account-to-account instant payments on Aani, including proxy lookup, request to pay and payment status handling.', 'Integration code or sandbox certification work; payment flow designs with status and failure handling', 'Can explain how an Aani payment differs from a card payment', 'Built an Aani payment or request-to-pay flow in a sandbox, with status and failure cases tested', 'Took an Aani integration live and owned its reconciliation and incident handling', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 2, 'desirable'),
  (1, 'payments_fintech', 'uae', 2, 'Local acquirer integration', 'Integrates acquirers that serve the UAE market, including their certification, dirham settlement files and supported card brands.', 'Integration code and certification records; settlement file handling with tests', 'Has processed a test payment through an acquirer serving the UAE market', 'Built and certified an integration with one such acquirer, including its settlement files', 'Ran several such acquirer integrations in production, with routing and reconciliation across them', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 2, 'desirable'),
  (1, 'payments_fintech', 'ksa', 0, 'mada scheme integration', 'Accepts mada debit cards, including scheme certification, routing and co-badged card handling.', 'Integration code and certification test results; routing rules for co-badged cards', 'Can explain how mada cards are routed and how they differ from international card payments', 'Built and certified mada acceptance, including co-badged card routing', 'Owned mada acceptance in production across channels, with approval and reconciliation data', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 2, 'desirable'),
  (1, 'payments_fintech', 'ksa', 1, 'SADAD bill payments', 'Integrates biller-side bill presentment and payment notifications for SADAD bill payments, and reconciles them.', 'Biller integration code; notification handlers with tests; reconciliation reports', 'Can explain the SADAD bill lifecycle from presentment to payment notification', 'Built bill upload and payment notification handling, with tests for duplicate and late notifications', 'Ran a SADAD biller integration in production, with reconciliation and exception handling owned', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 2, 'desirable'),
  (1, 'payments_fintech', 'ksa', 2, 'SAMA payment rules', 'Knows the SAMA rules for payment service providers and how they shape licensing, onboarding, limits and reporting.', 'Requirement documents or compliance write-ups that apply the rules; features built to meet them', 'Can name the SAMA licence categories for payment services and what each allows', 'Built or specified a feature to meet a SAMA payment rule, with the review trail', 'Led a product’s compliance with SAMA payment rules through licensing or inspection, with the evidence pack', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 2, 'desirable'),
  (1, 'payments_fintech', 'india', 0, 'UPI and NPCI rules', 'Integrates UPI collect, intent and mandate flows, and follows the NPCI operating rules for timeouts, status checks and disputes.', 'UPI integration code with status-check and timeout tests; dispute handling flows; certification work', 'Can explain the difference between UPI collect, intent and mandate flows', 'Built a UPI flow with pending-status checks, timeouts and reversals tested', 'Ran UPI payments in production at volume, with success-rate, dispute and reconciliation data owned', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 2, 'desirable'),
  (1, 'payments_fintech', 'india', 1, 'RBI payment aggregator guidelines', 'Knows the RBI payment aggregator rules, such as escrow handling, merchant due diligence and settlement timelines, and builds to them.', 'Requirement documents or compliance write-ups that apply the guidelines; escrow or settlement code built to meet them', 'Can explain what the guidelines require of a payment aggregator', 'Built or specified escrow, settlement or merchant onboarding to meet the guidelines, with the review trail', 'Led a product’s compliance with the guidelines through authorisation or audit, with the evidence pack', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 2, 'desirable'),
  (1, 'payments_fintech', 'india', 2, 'Card-on-file tokenisation', 'Replaces stored card numbers with network tokens for card-on-file payments, as the RBI rules require, including token lifecycle events.', 'Token provisioning and lifecycle integration code with tests; network token certification work; migration plans from stored card numbers to tokens', 'Can explain why stored card numbers were replaced with tokens for card-on-file payments', 'Built token provisioning and payment with tokens, handling token updates and deletions', 'Led a migration of stored cards to tokens with no loss of repeat payments, with the data to show it', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'uae', 0, 'CBUAE open finance framework', 'Knows the CBUAE open finance framework, its consent, API and security standards, and builds account and payment services to them.', 'Integration code or conformance results for the framework; consent flow designs; requirement documents that cite the standard they meet', 'Can explain what the framework covers and how a customer’s consent is captured and revoked', 'Built an API or client that passed the framework’s conformance tests, with consent handling tested', 'Took an open finance integration live and owned its consent, monitoring and incident handling', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'uae', 1, 'UAE PASS eKYC', 'Uses UAE PASS sign-in and verified identity data in onboarding, with the consent, assurance levels and fallback the integration rules require.', 'Integration code and sandbox test results; onboarding flow designs with fallback cases', 'Can explain what verified data UAE PASS shares and what each assurance level means', 'Built onboarding with UAE PASS in a sandbox, with consent, failure and fallback cases tested', 'Took UAE PASS onboarding live and owned its completion rates and incident handling', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'uae', 2, 'CBUAE AML/CFT and suspicious transaction reporting', 'Knows the CBUAE rules for AML/CFT controls and how suspicious transaction reports are filed with the financial intelligence unit, and builds monitoring and reporting to them.', 'Requirement documents or compliance write-ups that apply the rules; reporting integration code or designs', 'Can explain when a suspicious transaction report is due and what it must contain', 'Built or specified monitoring or reporting to meet the rules, with the review trail', 'Led a bank’s AML/CFT systems through a regulatory inspection, with the evidence pack', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'ksa', 0, 'SAMA open banking framework', 'Knows the SAMA open banking framework, its account information and payment initiation standards, and builds services to them.', 'Integration code or conformance results for the framework; consent flow designs; compliance write-ups that apply it', 'Can explain the phases of the framework and what each allows', 'Built an API or client that passed the framework’s conformance tests, with consent handling tested', 'Took an open banking integration live under the framework and owned its monitoring and incidents', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'ksa', 1, 'Nafath identity verification', 'Uses Nafath to verify identity and approve sign-ins and transactions in onboarding, including the app approval flow and its failure cases.', 'Integration code and sandbox test results; onboarding flow designs with timeout and rejection cases', 'Can explain how a Nafath approval request reaches the customer and returns a result', 'Built Nafath verification in a sandbox, with timeout, rejection and retry cases tested', 'Took Nafath verification live and owned its completion rates and incident handling', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'ksa', 2, 'SAMA Sharia governance framework', 'Knows how the SAMA Sharia governance framework shapes product approval, review and audit for Islamic banking, and keeps systems and records in line with it.', 'Product approval records and system controls that apply the framework; Sharia review or audit findings closed', 'Can explain the roles the framework gives the Sharia committee, review and audit', 'Built or specified system controls or records that a Sharia review relied on', 'Led systems work for a product through Sharia approval and audit, with the evidence pack', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'ksa', 3, 'SAMA cyber security framework', 'Applies the SAMA cyber security framework to banking systems, mapping each control to how the systems run and keeping the evidence an assessment needs.', 'Control mappings and assessment evidence; remediation records; compliance write-ups that apply it', 'Can explain the domains of the framework and which apply to a system', 'Mapped a system to the framework and closed the findings of its assessment', 'Led banking platforms through an assessment against the framework, with evidence kept current', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml', 'devops_sre']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'india', 0, 'Account aggregator consent flows', 'Integrates as a financial information provider or user in the RBI account aggregator framework, with consent artefacts, data fetch and revocation handled.', 'Integration code and sandbox certification; consent flow designs with tests for revocation and expiry', 'Can explain how a consent artefact, a data fetch and a revocation fit together', 'Built a provider or user integration that passed sandbox certification, with consent expiry tested', 'Took an account aggregator integration live and owned its consent, data quality and audit records', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'india', 1, 'Aadhaar eKYC and video KYC', 'Builds onboarding with Aadhaar eKYC and video-based customer identification as the RBI KYC rules allow, with consent, masking and storage limits.', 'Onboarding integration code with tests; designs for consent, number masking and storage; audit records', 'Can explain which eKYC and video KYC methods the RBI KYC rules allow and their limits', 'Built eKYC or video KYC onboarding with consent and masking, with the review trail', 'Ran eKYC or video KYC onboarding in production through audit, with completion and rejection data owned', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml']::text[], 2, 'desirable'),
  (1, 'banking_islamic_finance', 'india', 2, 'RBI digital lending guidelines', 'Knows the RBI digital lending guidelines, such as disbursal to the borrower’s own account, key fact statements and cooling-off periods, and builds lending flows to them.', 'Requirement documents or compliance write-ups that apply the guidelines; lending flow code built to meet them', 'Can explain what the guidelines require of a lending app and its partners', 'Built or specified a lending flow to meet the guidelines, with the review trail', 'Led a lending product’s compliance with the guidelines through audit, with the evidence pack', ARRAY['software_engineering', 'qa_test_automation', 'forward_deployed_engineering', 'product_management', 'data_ml']::text[], 2, 'desirable'),
